closeAlert(name) {
  dump(`closeAlert: ${name}\n`);
  if (MockAlertsService._closedDeferred) {
    if (name == MockAlertsService.alert.name) {
      MockAlertsService.listener?.observe(
        null,
        "alertfinished",
        MockAlertsService.alert.cookie
      );
      MockAlertsService._closedDeferred?.resolve();
    }
  }
